-- L08-K3-daily-bank.rollback.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   undoes L08. Refused while one of these rows is scheduled or already published.
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if exists (select 1 from public.quiz_bank where site_id = 'anime' and lower(btrim(title)) in ('who am i? heroes, hunters and a rubber body', 'twenty fingers and a strongest sorcerer', 'opening act: who sang it?', 'a notebook, an apple and a rule', 'pen names: who created these manga?', 'hum it, name it: which series opens with this song?', 'grand line trivia: songs, studios and fruits', 'sessions in 2071', 'who am i? elves, idols and a telepath', 'operation strix and the forger home', 'closing credits: ending song quiz', 'who am i? sleepers, soldiers and a strongest sorcerer', 'tokyo-3, 1995', 'sleeping sisters and boar masks', 'who sang it? true or false', 'straw hat statements: fact or fiction', 'odd one out: songs, singers and films', 'sound check: music trivia across the shelf', 'longships and four arcs', 'cursed energy soundtrack', 'who sang it? songs across the shelf', 'demon slayer sound test', 'who draws it? creators and their manga', 'longship statements: true or false', 'odd one out: born online or in print', 'naruto endings: roll the credits', 'jump newcomer: numbers and prizes', 'palace apothecary paper trail', 'the people behind tokyo-3', 'name the series: songs first', 'monster #8: awards and spin-offs', 'plus ultra playlist', 'naruto playlist: who sang the openings', 'dragon ball jukebox: openings and endings', 'from web novel to webtoon to film', 'from jump giga to jump comics', 'songs from beyond the walls') and (scheduled_date is not null or published_quiz_id is not null)) then
    raise exception 'L08 rollback refused: a bank row is scheduled or published';
  end if;
end $o1l$;

delete from public.quiz_bank where site_id = 'anime' and lower(btrim(title)) in ('who am i? heroes, hunters and a rubber body', 'twenty fingers and a strongest sorcerer', 'opening act: who sang it?', 'a notebook, an apple and a rule', 'pen names: who created these manga?', 'hum it, name it: which series opens with this song?', 'grand line trivia: songs, studios and fruits', 'sessions in 2071', 'who am i? elves, idols and a telepath', 'operation strix and the forger home', 'closing credits: ending song quiz', 'who am i? sleepers, soldiers and a strongest sorcerer', 'tokyo-3, 1995', 'sleeping sisters and boar masks', 'who sang it? true or false', 'straw hat statements: fact or fiction', 'odd one out: songs, singers and films', 'sound check: music trivia across the shelf', 'longships and four arcs', 'cursed energy soundtrack', 'who sang it? songs across the shelf', 'demon slayer sound test', 'who draws it? creators and their manga', 'longship statements: true or false', 'odd one out: born online or in print', 'naruto endings: roll the credits', 'jump newcomer: numbers and prizes', 'palace apothecary paper trail', 'the people behind tokyo-3', 'name the series: songs first', 'monster #8: awards and spin-offs', 'plus ultra playlist', 'naruto playlist: who sang the openings', 'dragon ball jukebox: openings and endings', 'from web novel to webtoon to film', 'from jump giga to jump comics', 'songs from beyond the walls');
